window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9e71742a3b3385e6"]={"versions": [{"id": "FIG-9e71742a3b3385e6", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des synchronen Empfangsablaufs einer I-PDU (Inter-Module PDU Communication) in der AUTOSAR Classic Platform. Das Diagramm modelliert den Kontroll- und Datenfluss von der CAN-Treiberschicht über den PDU Router direkt zum Kommunikationsmodul.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei als <code>«module»</code> typisierte Kommunikationsmodule entlang ihrer Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>CanIf</code>: Untere Schnittstellenschicht (CAN Interface).\n</li><li><code>PduR</code>: Zentraler PDU-Router (vermittelnde Instanz).\n</li><li><code>Com</code>: Obere Kommunikationsschicht (AUTOSAR COM, mit Unendlich- bzw. Prozess-Symbol markiert).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\"><li><code>PduR_&lt;User:Lo&gt;RxIndication(PduIdType, PduInfoType*)</code>: Indikations-Callback der unteren Schicht an den PDU-Router mit I-PDU-ID und Zeiger auf die PDU-Datenstruktur.\n</li><li><code>Com_RxIndication(PduIdType, PduInfoType*)</code>: Weiterleitung des Indikations-Aufrufs vom PduR an das COM-Modul.\n</li><li>Interne Operation <code>copy buffer()</code>: Lokale Pufferkopier-Routine innerhalb des COM-Moduls.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>CanIf</code> signalisiert den Empfang einer I-PDU synchron über den Aufruf <code>PduR_&lt;User:Lo&gt;RxIndication(PduIdType, PduInfoType*)</code> an den PduR; der Ausführungsbalken des PduR wird aktiviert.\n</li><li><code>PduR</code> leitet den Aufruf ohne interne Zwischenspeicherung direkt an <code>Com</code> über <code>Com_RxIndication(PduIdType, PduInfoType*)</code> weiter; der Ausführungsbalken von <code>Com</code> wird aktiviert.\n</li><li><code>Com</code> führt synchron eine interne Selbstaufruf-Operation <code>copy buffer()</code> aus, um die empfangenen Nutzdaten aus dem übergebenen Puffer in eigene Speicherbereiche zu kopieren.\n</li><li>Nach Abschluss des Kopiervorgangs kehrt der Kontrollfluss via gestrichelter Rückkehrpfeile synchron von <code>Com</code> zu <code>PduR</code> und anschließend von <code>PduR</code> zu <code>CanIf</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Sequenz veranschaulicht eine direkte I-PDU-Weiterleitung (1:1-Routing von CanIf zu Com). Gemäß der angehefteten Notiz („Reception of IPDU going directly to COM. No buffering in PduR is needed“) puffert der PDU Router die Nutzdaten nicht selbst. Der Zeiger <code>PduInfoType*</code> verweist auf den Puffer der unteren Schicht, weshalb das COM-Modul innerhalb des Indication-Kontexts die Nutzdaten synchron kopieren muss (<code>copy buffer()</code>), bevor der Aufruf zurückkehrt.</p>"}, {"id": "FIG-11293c1edb5540be", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des synchronen Empfangsablaufs einer I-PDU (Inter-Module PDU Communication) in der AUTOSAR Classic Platform. Das Diagramm modelliert den Kontroll- und Datenfluss von der CAN-Treiberschicht über den PDU Router direkt zum Kommunikationsmodul.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei als <code>«module»</code> typisierte Kommunikationsmodule entlang ihrer Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>CanIf</code>: Untere Schnittstellenschicht (CAN Interface).\n</li><li><code>PduR</code>: Zentraler PDU-Router.\n</li><li><code>Com</code>: Obere Kommunikationsschicht (AUTOSAR COM, mit Unendlich- bzw. Prozess-Symbol markiert).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\"><li><code>PduR_&lt;User:Lo&gt;RxIndication(PduIdType, const PduInfoType*)</code>: Indikations-Callback der unteren Schicht an den PDU-Router mit const-qualifiziertem Zeiger auf die PDU-Datenstruktur.\n</li><li><code>Com_RxIndication(PduIdType, const PduInfoType*)</code>: Weiterleitung der Empfangsmeldung vom PduR an das COM-Modul mit unveränderlichem Datenzeiger.\n</li><li>Interne Operation <code>copy buffer()</code>: Lokale Pufferkopier-Routine innerhalb des COM-Moduls.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>CanIf</code> signalisiert den Empfang einer I-PDU synchron über den Aufruf <code>PduR_&lt;User:Lo&gt;RxIndication(PduIdType, const PduInfoType*)</code> an den PduR; der Ausführungsbalken des PduR wird aktiviert.\n</li><li><code>PduR</code> leitet den Aufruf direkt an <code>Com</code> über <code>Com_RxIndication(PduIdType, const PduInfoType*)</code> weiter; der Ausführungsbalken von <code>Com</code> wird aktiviert.\n</li><li><code>Com</code> führt synchron eine interne Selbstaufruf-Operation <code>copy buffer()</code> aus, um die empfangenen Nutzdaten zu kopieren.\n</li><li>Der Kontrollfluss kehrt über gestrichelte Pfeile synchron von <code>Com</code> zu <code>PduR</code> und von <code>PduR</code> zu <code>CanIf</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Sequenz veranschaulicht eine direkte I-PDU-Weiterleitung ohne Pufferung im PDU Router („Reception of IPDU going directly to COM. No buffering in PduR is needed“). Die Verwendung von <code>const PduInfoType*</code> garantiert, dass Empfangsdaten im Aufrufkontext schreibgeschützt übergeben werden. Das COM-Modul ist dafür zuständig, die Daten synchron via <code>copy buffer()</code> zu sichern, bevor der Funktionsaufruf an die untere Schicht zurückkehrt.</p>"}, {"id": "FIG-ea94e718afacbae4", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des synchronen Empfangsablaufs einer I-PDU (Inter-Module PDU Communication) in der AUTOSAR Classic Platform. Das Diagramm modelliert den Kontroll- und Datenfluss von der CAN-Treiberschicht über den PDU Router direkt zum Kommunikationsmodul.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei als <code>«module»</code> typisierte Kommunikationsmodule entlang ihrer Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>CanIf</code>: Untere Schnittstellenschicht (CAN Interface).\n</li><li><code>PduR</code>: Zentraler PDU-Router.\n</li><li><code>Com</code>: Obere Kommunikationsschicht (AUTOSAR COM, mit Unendlich- bzw. Prozess-Symbol markiert).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\"><li><code>PduR_&lt;User:Lo&gt;RxIndication(PduIdType, const PduInfoType*)</code>: Indikations-Callback der unteren Schicht an den PDU-Router mit const-qualifiziertem Zeiger auf die PDU-Datenstruktur.\n</li><li><code>Com_RxIndication(PduIdType, const PduInfoType*)</code>: Weiterleitung der Empfangsmeldung vom PduR an das COM-Modul mit unveränderlichem Datenzeiger.\n</li><li>Interne Operation <code>copy buffer()</code>: Lokale Pufferkopier-Routine innerhalb des COM-Moduls.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>CanIf</code> signalisiert den Empfang einer I-PDU synchron über den Aufruf <code>PduR_&lt;User:Lo&gt;RxIndication(PduIdType, const PduInfoType*)</code> an den PduR; der Ausführungsbalken des PduR wird aktiviert.\n</li><li><code>PduR</code> leitet den Aufruf direkt an <code>Com</code> über <code>Com_RxIndication(PduIdType, const PduInfoType*)</code> weiter; der Ausführungsbalken von <code>Com</code> wird aktiviert.\n</li><li><code>Com</code> führt synchron eine interne Selbstaufruf-Operation <code>copy buffer()</code> aus, um die empfangenen Nutzdaten zu kopieren.\n</li><li>Der Kontrollfluss kehrt über gestrichelte Pfeile synchron von <code>Com</code> zu <code>PduR</code> und von <code>PduR</code> zu <code>CanIf</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Sequenz veranschaulicht eine direkte I-PDU-Weiterleitung ohne Pufferung im PDU Router („Reception of IPDU going directly to COM. No buffering in PduR is needed“). Die Verwendung von <code>const PduInfoType*</code> garantiert, dass Empfangsdaten im Aufrufkontext schreibgeschützt übergeben werden. Das COM-Modul ist dafür zuständig, die Daten synchron via <code>copy buffer()</code> zu sichern, bevor der Funktionsaufruf an die untere Schicht zurückkehrt.</p>"}, {"id": "FIG-55a8d17f8b7f48a9", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des synchronen Empfangsablaufs einer I-PDU (Inter-Module PDU Communication) in der AUTOSAR Classic Platform. Das Diagramm modelliert den Kontroll- und Datenfluss von der CAN-Treiberschicht über den PDU Router direkt zum Kommunikationsmodul.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei als <code>«module»</code> typisierte Kommunikationsmodule entlang ihrer Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>CanIf</code>: Untere Schnittstellenschicht (CAN Interface).\n</li><li><code>PduR</code>: Zentraler PDU-Router.\n</li><li><code>Com</code>: Obere Kommunikationsschicht (AUTOSAR COM, mit Unendlich- bzw. Prozess-Symbol markiert).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\"><li><code>PduR_&lt;User:Lo&gt;RxIndication(PduIdType, const PduInfoType*)</code>: Indikations-Callback der unteren Schicht an den PDU-Router mit const-qualifiziertem Zeiger auf die PDU-Datenstruktur.\n</li><li><code>Com_RxIndication(PduIdType, const PduInfoType*)</code>: Weiterleitung der Empfangsmeldung vom PduR an das COM-Modul mit unveränderlichem Datenzeiger.\n</li><li>Interne Operation <code>copy buffer()</code>: Lokale Pufferkopier-Routine innerhalb des COM-Moduls.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>CanIf</code> signalisiert den Empfang einer I-PDU synchron über den Aufruf <code>PduR_&lt;User:Lo&gt;RxIndication(PduIdType, const PduInfoType*)</code> an den PduR; der Ausführungsbalken des PduR wird aktiviert.\n</li><li><code>PduR</code> leitet den Aufruf direkt an <code>Com</code> über <code>Com_RxIndication(PduIdType, const PduInfoType*)</code> weiter; der Ausführungsbalken von <code>Com</code> wird aktiviert.\n</li><li><code>Com</code> führt synchron eine interne Selbstaufruf-Operation <code>copy buffer()</code> aus, um die empfangenen Nutzdaten zu kopieren.\n</li><li>Der Kontrollfluss kehrt über gestrichelte Pfeile synchron von <code>Com</code> zu <code>PduR</code> und von <code>PduR</code> zu <code>CanIf</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Sequenz veranschaulicht eine direkte I-PDU-Weiterleitung ohne Pufferung im PDU Router („Reception of IPDU going directly to COM. No buffering in PduR is needed“). Die Verwendung von <code>const PduInfoType*</code> garantiert, dass Empfangsdaten im Aufrufkontext schreibgeschützt übergeben werden. Das COM-Modul ist dafür zuständig, die Daten synchron via <code>copy buffer()</code> zu sichern, bevor der Funktionsaufruf an die untere Schicht zurückkehrt.</p>"}], "trans": [{"from": "FIG-9e71742a3b3385e6", "to": "FIG-11293c1edb5540be", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Parameter in Funktionsaufrufen <code>PduR_&lt;User:Lo&gt;RxIndication</code> und <code>Com_RxIndication</code>: Typ des zweiten Arguments von <code>PduInfoType*</code> auf <code>const PduInfoType*</code> geändert (Const-Qualifizierung des Zeigers).\n</li></ul>"}, {"from": "FIG-11293c1edb5540be", "to": "FIG-ea94e718afacbae4", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ea94e718afacbae4", "to": "FIG-55a8d17f8b7f48a9", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
